def score(A, V):
    B = np.linalg.lstsq(A, V, rcond=None)[0]
    R = A @ B - V
    U = np.linalg.svd(A, full_matrices=False)[0]
    h = (U ** 2).sum(1)
    return (np.mean(abs(R / (1 - h[:, None]))), B)

def poly(x, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(x))] + [np.prod(x[:, i], axis=1) for k in range(1, d + 1) for i in combinations_with_replacement(range(4), k)])

def panel(p, k, mode):
    from scipy.optimize import least_squares
    u = p['u']
    v = p[k]
    fit = np.linalg.lstsq

    def design(x, h):
        a = poly(x, 1)
        if k == 'v1':
            w = h[0]
            f = np.tanh(w * x)
            if mode == 1:
                f = f + h[1] * x ** 3
            if mode == 2:
                f = f + h[1] * np.sin(h[2] * x)
            if mode == 3:
                f = f + h[1] * x / (1 + (h[2] * x) ** 2)
            if mode == 4:
                f = f + h[1] * x * x
            if mode == 5:
                f = f + h[1] * np.cos(h[2] * x)
        else:
            w = h[0]
            f = x * x + h[1] * (np.cos(w * x) - 1) if mode == 0 else x * x + h[1] * (1 / (1 + (w * x) ** 2) - 1)
        return np.c_[a, f]

    def residual(h, loo=False):
        d = design(u, h)
        (q, _) = np.linalg.qr(d)
        r = v - q @ (q.T @ v)
        return r / (1 - (q * q).sum(1, keepdims=True)) if loo else r
    if k == 'v1':
        starts = {0: [[2.3]], 1: [[2.3, 0]], 2: [[w, c, j] for w in [1, 2.3, 3] for c in [-0.3, 0.3] for j in [1.5, 3]], 3: [[w, c, j] for w in [1, 2.3, 3] for c in [-0.3, 0.3] for j in [0.8, 2]], 4: [[2.3, 0]], 5: [[2.3, 0.05, j] for j in [1, 2, 3]]}[mode]
    else:
        starts = [[w, -0.2] for w in [1, 2.3, 3]] if mode == 0 else [[w, -1] for w in [0.5, 1, 2]]
    opts = [least_squares(lambda h: residual(h).ravel(), start, max_nfev=300) for start in starts]
    r = min(opts, key=lambda r: np.mean(residual(r.x, True) ** 2))
    d = design(u, r.x)
    b = fit(d, v, rcond=None)[0]
    e = np.sqrt(np.mean(residual(r.x, True) ** 2))
    print(k, mode, r.x.round(5), round(e, 7))
    return (e, lambda x: design(x, r.x) @ b)
